    # Focus: Strong deadline enforcement with bottleneck-aware routing
    current_time = state['current_time']
    litho_queue = state['litho_queue']
    litho_util = state['litho_utilization']
    hot_count = state['hot_lot_count']

    # Base priority: inverse of remaining processing time (favor shorter jobs)
    score = -task.estimated_remaining

    # HOT lot handling: exponential urgency based on deadline proximity
    if task.priority.value == 4:
        if task.deadline is not None:
            slack = task.deadline - current_time
            if slack <= 0:
                score += 2000  # Already late, maximum boost
            else:
                # Exponential urgency: 1000 / (slack^0.5) for steep penalty as deadline approaches
                score += 1000.0 / (slack ** 0.5 + 1.0)
        else:
            score += 50.0  # No deadline but still hot

    # URGENT lots: moderate deadline sensitivity
    elif task.priority.value == 3:
        if task.deadline is not None:
            slack = task.deadline - current_time
            if slack <= 0:
                score += 800
            else:
                score += 300.0 / (slack + 1.0)
        else:
            score += 20.0

    # NORMAL lots: small base boost
    elif task.priority.value == 2:
        score += 5.0

    # RESEARCH lots: no extra boost
    else:
        score -= 10.0

    # Queue wait time fairness (linear to prevent starvation)
    score += task.queue_wait_time * 1.0

    # Bottleneck-aware routing: strong penalty for litho-bound jobs when litho is congested
    if litho_queue > 3 and litho_util > 0.7:
        # Check if next step is litho (re-entrant pattern: every 5 steps)
        step_in_cycle = (20 - task.remaining_steps) % 5
        if step_in_cycle == 0:  # Next step is litho
            score -= 30.0  # Strong penalty to deprioritize
        else:
            score += 15.0  # Boost non-litho jobs to clear other machines

    # Objective adaptation
    if state['objective'] == 'hot_lot_tardiness':
        if task.priority.value == 4:
            score *= 3.0  # Triple hot lot priority for tardiness objective
        elif task.priority.value == 3:
            score *= 1.5
    elif state['objective'] == 'cycle_time':
        # Balance: give more weight to queue wait time for fairness
        score += task.queue_wait_time * 0.8
    elif state['objective'] == 'carbon':
        # Penalize litho steps more heavily to reduce energy consumption
        step_in_cycle = (20 - task.remaining_steps) % 5
        if step_in_cycle == 0:
            score -= 10.0  # Additional penalty for litho-bound jobs

    return score

