            if slack < 0:
                base += 500
            elif slack < 48:
                base += 200 - slack * 3
        base += task.queue_wait_time * 1.5
    else:  # NORMAL or RESEARCH
        base += task.queue_wait_time * 1.0  # FIFO pressure

    # Litho awareness: only penalize when truly congested
    going_to_litho = (task.remaining_steps % 5 == 0) and task.remaining_steps > 0
