def priority(task, state):
    # Bottleneck-aware earliest deadline with litho queue penalty
    # When litho queue is high, push non-litho lots first to clear bottleneck
    # When litho queue is low, push litho lots to keep bottleneck fed

    hot_bonus = 100 if task.priority.value == 4 else 0

    # Calculate deadline urgency (if exists)
    if task.deadline is not None:
        slack = task.deadline - state['current_time']
        deadline_urgency = 1.0 / (slack + 1.0)
    else:
        deadline_urgency = 0.0

    # Check if next step is litho
    is_litho_next = (task.remaining_steps % 5 == 1)  # LITHO is every 5th step

    # Litho queue penalty: penalize litho-bound lots when queue is high
    litho_queue = state['litho_queue']
    if is_litho_next:
        if litho_queue > 5:
            litho_penalty = -20  # Deprioritize litho-bound when queue is full
        else:
            litho_penalty = 10   # Prioritize litho-bound when queue is low
    else:
        if litho_queue > 5:
            litho_penalty = 20   # Push non-litho lots when litho is busy
        else:
            litho_penalty = 0

    # Remaining work urgency (short jobs first to keep flow)
    remaining_work = task.estimated_remaining

    return hot_bonus + deadline_urgency * 50 + litho_penalty - remaining_work * 0.5

def priority(task, state):
    # Bottleneck-aware: Penalize lots going to LITHO when queue is high
    # Reward lots with few remaining steps (near completion)
    # Uses LWKR (Least Work Remaining) scaled by priority
