        if slack < 0:
            base_score = 10000.0  # Overdue gets highest priority
        elif slack < 2:
            base_score = 5000.0
        elif slack < 5:
            base_score = 2000.0 - slack * 100
        else:
            base_score = max(100.0, 500.0 - slack * 10)
    else:
        # No deadline: use remaining steps as proxy (FIFO-like)
        base_score = 100.0 + (20 - task.remaining_steps) * 5

    # Priority multiplier
    if task.priority.value == 4:  # HOT
        base_score *= 5.0
    elif task.priority.value == 3:  # URGENT
        base_score *= 2.5
    elif task.priority.value == 1:  # RESEARCH
        # Research lots: penalize when litho busy, boost when litho idle
        if litho_util > 0.7 or litho_queue > 5:
            base_score *= 0.3  # Heavy penalty to not block bottleneck
        elif litho_util < 0.3 and litho_queue < 2:
            base_score *= 1.5  # Slight boost when litho idle
        else:
            base_score *= 0.7  # Moderate penalty otherwise

    # Going to litho next? Check remaining_steps pattern
    going_to_litho = (task.remaining_steps % 5 == 4) or (task.remaining_steps == 20)

    # Litho congestion management
    if going_to_litho:
        if litho_queue > 6:
            base_score *= 0.2  # Strongly discourage feeding bottleneck
        elif litho_queue > 3:
            base_score *= 0.5
    else:
        if litho_queue > 6:
            base_score *= 2.0  # Boost non-litho to clear system
        elif litho_queue > 3:
            base_score *= 1.4

    # Wait time bonus (linear, prevents starvation)
    base_score += task.queue_wait_time * 0.8

    return base_score

def priority(task, state):
    # LWKR (Least Work Remaining) with bottleneck-aware penalty
    # Prioritize lots with less remaining work to reduce WIP, but
    # dynamically penalize litho-bound lots when litho is congested

    # Base: inverse of estimated remaining (less work = higher priority)
    base = -task.estimated_remaining * 0.5

