            slack = task.deadline - state['current_time'] - task.estimated_remaining
            if slack < 0:
                base += 10000  # Already late
            elif slack < 5:
                base += 5000   # Very tight
            else:
                base += 2000   # Hot but comfortable
        else:
            base += 1000

    # Urgent lots (priority 3) get moderate boost
    if task.priority.value == 3:
        if task.deadline is not None:
            slack = task.deadline - state['current_time'] - task.estimated_remaining
            if slack < 0:
                base += 5000
            elif slack < 5:
                base += 2000
            else:
                base += 500

    # Detect if next step is litho (based on step pattern: steps 0,5,10,15 are litho)
    # Remaining_steps goes from 20 down to 0; litho at steps 20,15,10,5 (remaining)
    going_to_litho = task.remaining_steps in [20, 15, 10, 5]

    # Bottleneck-aware routing: penalize litho-bound lots when litho is congested
    if state['litho_queue'] > 6:
        if going_to_litho:
            base -= 300  # Strong penalty to avoid feeding the bottleneck
        else:
            base += 100  # Boost non-litho lots to clear other machines
    elif state['litho_queue'] > 3:
        if going_to_litho:
            base -= 100
        else:
            base += 50

    # When litho is underutilized, push litho-bound lots through
    if state['litho_utilization'] < 0.6 and state['litho_queue'] < 3:
        if going_to_litho:
            base += 200  # Feed the bottleneck when it's idle

    # R&D lots (priority 1): only schedule when litho is not congested
    if task.priority.value == 1:
        if state['litho_queue'] > 4:
            base -= 500  # Deprioritize during congestion
        else:
            base += 50   # Small boost when idle

    # FIFO tiebreaker within same priority level
    base += task.queue_wait_time * 0.05

    return base

def priority(task, state):
    # Strategy: Bottleneck-aware FIFO with hot-lot override and dynamic slack
    # This uses arrival time as baseline, but with strong litho congestion avoidance
    # and hot lot deadline urgency that overrides everything else

    # Hot lot handling: absolute deadline urgency
    if task.priority.value == 4 and task.deadline is not None:
