        elif slack < 3:
            return 8000.0 - slack * 500  # Critical: 8000-8500 range
        elif slack < 8:
            return 5000.0 - slack * 200  # Urgent: 3400-5000 range
        else:
            return 3000.0  # Still hot

    # URGENT lots get moderate boost
