def priority(task, state):
    # Strategy: Dynamic Bottleneck Pressure with Tardiness Escalation
    # Uses real-time litho pressure to dynamically adjust between 
    # feeding the bottleneck vs. protecting it from overload

    # Base priority mapping with exponential scale
    priority_weights = {4: 1000, 3: 100, 2: 10, 1: 1}
    base = priority_weights.get(task.priority.value, 1)

    # Calculate slack and tardiness
    slack = float('inf')
    if task.deadline is not None:
        slack = task.deadline - state['current_time']

    # Tardiness factor (exponential for HOT, linear for others)
    if task.priority.value == 4:
        if slack < 0:
            tardiness = 5000 * (1 + abs(slack) / 12)
        elif slack < 6:
            tardiness = 2000 * (1 - slack / 6)
        else:
            tardiness = base * 10 / max(1, slack)
    else:
        if slack < 0:
            tardiness = 500 * (1 + abs(slack) / 24)
        elif slack < 12:
            tardiness = 200 * (1 - slack / 12)
        else:
            tardiness = base / max(1, slack)

    # Identify next step type
    steps_done = 20 - task.remaining_steps
    next_step = (steps_done + 1) % 5
    next_is_litho = (next_step == 0)  # Steps 5, 10, 15, 20 are litho

    # Bottleneck pressure calculation
    litho_pressure = state['litho_queue'] * (1 + state['litho_utilization'])
    hot_proportion = state['hot_lot_count'] / max(1, state['queue_length'])

    # Dynamic pressure-based adjustment
    if next_is_litho:
        if litho_pressure > 8:
            # Heavy congestion: penalize feeding litho unless HOT
            if task.priority.value == 4:
                pressure_adjust = -litho_pressure * 5
            else:
                pressure_adjust = -litho_pressure * 20
        elif litho_pressure > 4:
            # Moderate congestion: slight penalty
            pressure_adjust = -litho_pressure * 3
        else:
            # Low congestion: slight boost to keep litho fed
            pressure_adjust = 10 * (1 - litho_pressure / 4)
    else:
        if litho_pressure > 8:
            # Heavy litho congestion: boost non-litho to clear other queues
            pressure_adjust = 30 * hot_proportion + 15
        elif litho_pressure > 4:
            pressure_adjust = 10 * hot_proportion + 5
        else:
            pressure_adjust = 0

    # Processing time urgency (shorter remaining = higher priority for non-litho)
    proc_urgency = 1.0 / max(0.1, task.estimated_remaining)

    # Starvation prevention (exponential wait boost)
    wait_boost = min(50, task.queue_wait_time ** 1.5 * 2)

    # Final score
    score = (base * 100 + tardiness + pressure_adjust + 
             proc_urgency * 50 + wait_boost)

    return score

